import{_ as t,o as r,c as a,a3 as o}from"./chunks/framework.Btk6PxWC.js";const p=JSON.parse('{"title":"WebGPU notes","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://kilnrender.com/preview/feat-labels-data/reference/webgpu.html"}],["meta",{"property":"og:title","content":"WebGPU notes | Kiln"}],["meta",{"property":"og:description","content":"A WebGPU renderer that streams large volumetric datasets over HTTP into a bounded VRAM cache."}],["meta",{"property":"og:url","content":"https://kilnrender.com/preview/feat-labels-data/reference/webgpu.html"}],["meta",{"name":"twitter:title","content":"WebGPU notes | Kiln"}],["meta",{"name":"twitter:description","content":"A WebGPU renderer that streams large volumetric datasets over HTTP into a bounded VRAM cache."}]]},"headers":[],"relativePath":"reference/webgpu.md","filePath":"reference/webgpu.md"}'),d={name:"reference/webgpu.md"};function n(s,e,i,c,l,u){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="webgpu-notes" tabindex="-1">WebGPU notes <a class="header-anchor" href="#webgpu-notes" aria-label="Permalink to &quot;WebGPU notes&quot;">​</a></h1><p>What Kiln relies on in WebGPU, and how it compares to WebGL 2 for volume rendering.</p><h2 id="_16-bit-textures" tabindex="-1">16-bit textures <a class="header-anchor" href="#_16-bit-textures" aria-label="Permalink to &quot;16-bit textures&quot;">​</a></h2><p><code>uint16</code> is stored bit-exact as <code>r16unorm</code> only when the device accepts it as a <strong>filterable 3D texture</strong>. The optional <code>texture-formats-tier1</code> feature alone doesn&#39;t guarantee that: an implementation may expose <code>r16unorm</code> as <code>unfilterable-float</code> only. <code>KilnEngine.createDevice()</code> requests the feature when offered, and setup validates a small texture against the shaders&#39; <code>float</code> binding inside an error scope before choosing the format.</p><p>Fallback chain:</p><ol><li><strong><code>r16unorm</code></strong>: bit-exact; needs <code>texture-formats-tier1</code> and passing validation</li><li><strong><code>r16float</code></strong>: core and filterable. Half floats hold every integer in [−2048, 2048], so Kiln stores <code>value − 2048</code>: 12-bit data stays exact, higher values get half-float precision. <code>int16</code> and <code>float32</code> always use this format, as raw values normalised in the shader</li><li><strong><code>r8unorm</code></strong>: last resort; workers keep the high byte. Logs a warning and shows &quot;(⚠️ downsampled)&quot; in the UI</li></ol><p>WebGL 2 has <code>R16F</code> in core, but <code>R16</code> only through <code>EXT_texture_norm16</code>, and filterable <code>R32F</code> needs <code>OES_texture_float_linear</code>.</p><h2 id="compute-shaders" tabindex="-1">Compute shaders <a class="header-anchor" href="#compute-shaders" aria-label="Permalink to &quot;Compute shaders&quot;">​</a></h2><p>The ray marcher is a compute shader, one thread per pixel. For the core loop this is equivalent to a fragment shader on a fullscreen triangle, but compute keeps the pipeline simple:</p><ul><li>results are written with <code>textureStore</code>, no framebuffer setup</li><li>temporal accumulation chains compute to compute, without render-pass transitions</li><li>resolution scaling is a smaller dispatch instead of an intermediate framebuffer and blit</li><li>no vertex stage or rasterizer</li></ul><p>Kiln doesn&#39;t use shared memory, subgroups or indirect dispatch yet; compute leaves room for them.</p><h2 id="other-differences" tabindex="-1">Other differences <a class="header-anchor" href="#other-differences" aria-label="Permalink to &quot;Other differences&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>WebGL 2</th><th>WebGPU</th></tr></thead><tbody><tr><td>16-bit textures</td><td><code>R16F</code> core, <code>R16</code> via extension</td><td><code>r16float</code> core, <code>r16unorm</code> via <code>texture-formats-tier1</code></td></tr><tr><td>3D texture size</td><td>256³ guaranteed, typically 2048³</td><td>2048³ guaranteed, more if the adapter allows</td></tr><tr><td>Compute shaders</td><td>no</td><td>yes</td></tr><tr><td>Texture uploads</td><td><code>texSubImage3D</code>, synchronous on the CPU timeline</td><td><code>queue.writeTexture</code>, queued</td></tr><tr><td>Integer textures</td><td>yes, with fewer formats</td><td>yes; <code>textureLoad</code> reads them exactly</td></tr></tbody></table><p>Kiln&#39;s largest atlas, 660³ per channel, fits the guaranteed 3D size, and <code>createDevice()</code> requests the adapter&#39;s maximum anyway. Capable WebGL volume renderers exist; WebGPU maps more directly onto what streaming virtual textures need.</p>',14)])])}const m=t(d,[["render",n]]);export{p as __pageData,m as default};
